def main():
    sources = json.loads(Path("source.json").read_text())
    result = []
    for source in sources:
        spec = NOTES[source["number"]]
        item = {key: source[key] for key in ("code_id", "source_id", "source_sha256", "number")}
        item.update(
            proposed_xml=Path(spec["file"]).read_text().strip(),
            reason=spec["reason"],
            review_notes=spec["review_notes"],
            status="rewrite_draft",
        )
        for key in ("change_type", "reform_policy_id", "removed_provisions"):
            if key in spec:
                item[key] = spec[key]
        result.append(item)
    Path("answer.json").write_text(json.dumps(result, ensure_ascii=False, indent=2) + "\n")


if __name__ == "__main__":
    main()
